import functools
import time
import inspect

# 1. 带参数的重试装饰器（三层闭包）
def retry(max_attempts=3, delay=1, backoff=2, exceptions=(Exception,)):
    """最外层：接收装饰器参数，返回中间层 decorator"""
    def decorator(func):
        """中间层：接收被装饰函数，返回最内层 wrapper"""
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            """最内层：每次调用时执行，含重试逻辑"""
            last_exception = None
            for attempt in range(1, max_attempts + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as e:
                    last_exception = e
                    if attempt == max_attempts:
                        raise
                    wait = delay * (backoff ** (attempt - 1))
                    time.sleep(wait)
            raise last_exception
        return wrapper
    return decorator

@retry(max_attempts=5, delay=0.5, exceptions=(ConnectionError, TimeoutError))
def fetch_data(url):
    """可能失败的网络请求"""
    print(f"Fetching {url}...")
    raise ConnectionError("timeout")

# @wraps 的效果：函数名和文档保留
print(fetch_data.__name__)   # "fetch_data" 而非 "wrapper"
print(fetch_data.__wrapped__) # <function fetch_data at 0x...>

# 2. 多装饰器叠放的顺序
import functools, time

def log_call(func):
    @functools.wraps(func)
    def wrapper(*a, **kw):
        print(f"[LOG] calling {func.__name__}")
        return func(*a, **kw)
    return wrapper

@log_call          # 最后装饰，最先执行
@retry(max_attempts=3)  # 先装饰，最后执行
def unstable_api():
    print("  executing unstable_api")
    raise ConnectionError("fail")

# 调用时：log_call 进入 → retry 进入 → 原函数 → retry 返回 → log_call 返回

# 3. @property 是内置类装饰器
class Person:
    def __init__(self, name):
        self._name = name

    @property
    def name(self):
        """name 是一个描述符，不是普通方法"""
        return self._name

    @name.setter
    def name(self, value):
        if not isinstance(value, str) or not value.strip():
            raise TypeError("name must be a non-empty string")
        self._name = value.strip()

# 4. inspect.signature 验证 @wraps 的效果
def no_wrap_decorator(func):
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

def with_wrap_decorator(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

def sample(a: int, b: str = "hello") -> bool:
    return True

print(inspect.signature(no_wrap_decorator(sample)))   # (*args, **kwargs)
print(inspect.signature(with_wrap_decorator(sample))) # (a: int, b: str = 'hello') -> bool
